package ama.storage;
import ama.transcript.*;import ama.model.*;import ama.task.*;import ama.worker.*;import java.util.*;import java.util.concurrent.atomic.*;import org.junit.jupiter.api.AfterEach;import static org.junit.jupiter.api.Assertions.*;
class Task09GenerationPhysicalCancelIT extends Task09GenerationRichIT {
 Task09ControlledRelay relay;final AtomicReference<WorkerLoop> actualWorker=new AtomicReference<>();final AtomicBoolean eof=new AtomicBoolean();
 @Override String expectedImmediateTaskState(){return "RECONCILING";}
 @Override void workerStarted(WorkerLoop worker){actualWorker.set(worker);}
 @Override ControlledMinutesClient controlledClient(int port){try{relay=new Task09ControlledRelay(port,()->actualWorker.get().close());relay.dropPostResponse=true;relay.postSocket=socket->{try{socket.setSoTimeout(5000);assertEquals(-1,socket.getInputStream().read(),"Real client socket must close on WorkerLoop shutdown");eof.set(true);}catch(Exception e){throw new IllegalStateException(e);}};return new ControlledMinutesClient(new ControlledMinutesHttpTransport(java.net.URI.create("http://127.0.0.1:"+relay.port()),"task09-owned-provider-test-authorization-value","CONTROLLED_INSTALLATION",java.time.Duration.ofSeconds(2),java.time.Duration.ofSeconds(30),java.time.Duration.ofSeconds(5)));}catch(Exception e){throw new IllegalStateException(e);}}
 @Override void afterWorker(String task,MinutesExternalPreparation preparation,ControlledMinutesClient client,JdbcExternalOperations operations,JdbcModelPermitPool permits,Throwable failure)throws Exception{
  assertNotNull(failure);long closeEnd=System.nanoTime()+java.util.concurrent.TimeUnit.SECONDS.toNanos(8);while(!eof.get()&&System.nanoTime()<closeEnd)Thread.sleep(25);assertTrue(eof.get());assertNull(relay.failure.get());assertEquals(1,relay.posts.get());var before=j.queryForMap("SELECT e.id execution_id,e.state execution_state,o.state operation_state,r.settled_at FROM external_execution e JOIN external_operation o ON o.id=e.operation_id JOIN model_reservation r ON r.execution_id=e.id WHERE e.task_id=?",task);assertEquals("MARKED",before.get("execution_state"));assertEquals("MARKED",before.get("operation_state"));assertNull(before.get("settled_at"));assertEquals(0,j.queryForObject("SELECT COUNT(*) FROM generation_candidate WHERE task_id=?",Integer.class,task));var files=seals();java.nio.file.Files.writeString(receipt.resolve("actual-physical-cancel-before-recovery.json"),json.writeValueAsString(Map.of("task",task,"execution",before.get("execution_id"),"workerShutdown",true,"socketEofObserved",true,"permitSettled",false,"executionState","MARKED","providerPostCount",1,"providerFiles",files)));
  recoverCancelled(task,preparation,client,operations,permits,before,files);
 }
 void recoverCancelled(String task,MinutesExternalPreparation preparation,ControlledMinutesClient client,JdbcExternalOperations operations,JdbcModelPermitPool permits,Map<String,Object> before,Map<String,String> files)throws Exception{
  ama.contract.ExternalContracts.OperationToken token=null;long end=System.nanoTime()+java.util.concurrent.TimeUnit.SECONDS.toNanos(35);while(token==null&&System.nanoTime()<end){token=operations.claimReconciliation("TASK09_CANCEL_RECOVERY").orElse(null);if(token==null)Thread.sleep(100);}assertNotNull(token);assertEquals(before.get("execution_id"),token.executionId());var request=preparation.prepareLookup(token);var wire=client.prepare(request.body(token.executionId()),request.envelope());var remote=client.lookup(wire,NEVER);assertEquals("SUCCEEDED",remote.state());assertEquals(ama.contract.ExternalContracts.ObservationResult.APPLIED,operations.observePrepared(token,preparation.accept(request,token,wire,remote,NEVER)));assertEquals(1,permits.recoverSettlements(64));assertEquals(1,relay.posts.get());assertEquals(files,seals());java.nio.file.Files.writeString(receipt.resolve("actual-physical-cancel-recovery.json"),json.writeValueAsString(Map.of("task",task,"execution",token.executionId(),"result",remote.resultId(),"lookupOnly",true,"permitSettled",true,"providerPostCount",1)));
 }
 Map<String,String> seals()throws Exception{var out=new TreeMap<String,String>();try(var files=java.nio.file.Files.walk(providerStore)){for(var file:files.filter(java.nio.file.Files::isRegularFile).toList())out.put(providerStore.relativize(file).toString(),HexFormat.of().formatHex(java.security.MessageDigest.getInstance("SHA-256").digest(java.nio.file.Files.readAllBytes(file))));}return out;}
 @AfterEach void closeRelay()throws Exception{if(relay!=null)relay.close();}
}
